document.addEventListener('DOMContentLoaded',()=>{const menu=document.querySelector('.menu');const nav=document.querySelector('nav');if(menu&&nav)menu.addEventListener('click',()=>nav.classList.toggle('open'));const search=document.querySelector('.search button');const input=document.querySelector('.search input');if(search&&input)search.addEventListener('click',()=>{const q=input.value.trim();window.location.href=q?`shop.html?q=${encodeURIComponent(q)}`:'shop.html'});if(input)input.addEventListener('keydown',e=>{if(e.key==='Enter')search?.click()})});